data_labeled = ["PPO", "SAC", "TRPO", "RPO"]
Data = [PPO_thrust, SAC_thrust, TRPO_thrust, RPO_thrust]

# --- timing ---
dt_sim = 1 / 400
decimation = 2
dt_policy = dt_sim * decimation

# --- physics ---
g = 9.81
m_total = 2.0          # <-- set your total mass here (drone + payload) in kg
num_motors = 6

plt.rcParams.update({
    "font.size": 16,
    "axes.titlesize": 18,
    "axes.labelsize": 18,
    "xtick.labelsize": 14,
    "ytick.labelsize": 14,
    "legend.fontsize": 14
})

plt.figure(figsize=(10, 6))

for label, y in zip(data_labeled, Data):
    y = np.asarray(y, dtype=float)
    if len(y) == 0:
        continue

    time = np.arange(len(y)) * dt_policy

    # total thrust [N]
    total_thrust = y * num_motors

    # thrust-to-weight ratio
    tw_ratio = total_thrust / (m_total * g)

    plt.plot(time, tw_ratio, linewidth=2.5, label=label)

plt.title("Thrust-to-Weight Ratio (T/W)")
plt.xlabel("Time [s]")
plt.ylabel("(T / W) Ratio")
plt.axhline(1.0, linestyle="--", linewidth=2, color="k", label="Hover (T/W=1)")
plt.grid(True)
plt.legend()
plt.tight_layout()
plt.show()
import numpy as np

print("\nOVERALL THRUST-TO-WEIGHT RATIO COMPARISON")
print("-" * 50)
print(f"{'Algorithm':<10} {'Avg T/W':<15}")
print("-" * 50)

for label, y in zip(data_labeled, Data):

    y = np.asarray(y, dtype=float)
    if len(y) == 0:
        continue

    total_thrust = y * num_motors
    tw_ratio = total_thrust / (m_total * g)

    avg_twr = np.mean(tw_ratio)

    print(f"{label:<10} {avg_twr:<15.4f}")
    print(label, np.min(tw_ratio), np.max(tw_ratio))
print("-" * 50)